          prompt: 'Explain the process of allopatric speciation using a river as the geographic barrier, describing how the two resulting populations could eventually become separate species.',
          answer:
            'If a river forms and physically divides a single population into two separate groups, gene flow between the two groups is prevented, since individuals can no longer freely cross the river to interbreed. Each isolated population then continues to evolve independently, accumulating different mutations and experiencing different selection pressures and/or genetic drift on each side of the river. Given enough time, the accumulated genetic differences between the two populations may become so great that, even if the river later dried up or the two populations were reunited, individuals from the two groups could no longer interbreed successfully to produce fertile offspring, meaning they have become two separate species.',
